265:     private static Dictionary<long, DebugImage> LoadDebugImagesOnce(IDiagnosticLogger? logger)
266:     {
267:         logger?.LogDebug("Collecting a list of native debug images.");
268:         var result = new Dictionary<long, DebugImage>();
269:         try
270:         {
271:             var cList = sentry_get_modules_list();
272:             try
273:             {
274:                 if (!IsNull(cList))
275:                 {
276:                     var len = sentry_value_get_length(cList).ToUInt32();
277:                     logger?.LogDebug("There are {0} native debug images, parsing the information.", len);
278:                     for (uint i = 0; i < len; i++)
279:                     {
280:                         var cItem = sentry_value_get_by_index(cList, (UIntPtr)i);
281:                         if (!IsNull(cItem))
282:                         {
283:                             // See possible values present in `cItem` in the following files (or their latest versions)
284:                             // * https://github.com/getsentry/sentry-native/blob/8faa78298da68d68043f0c3bd694f756c0e95dfa/src/modulefinder/sentry_modulefinder_windows.c#L81
285:                             // * https://github.com/getsentry/sentry-native/blob/8faa78298da68d68043f0c3bd694f756c0e95dfa/src/modulefinder/sentry_modulefinder_windows.c#L24
286:                             // * https://github.com/getsentry/sentry-native/blob/c5c31e56d36bed37fa5422750a591f44502edb41/src/modulefinder/sentry_modulefinder_linux.c#L465
287:                             if (GetValueString(cItem, "image_addr") is { } imageAddr && imageAddr.Length > 0)
288:                             {
289:                                 var imageAddress = imageAddr.ParseHexAsLong();
290:                                 result.Add(imageAddress, new DebugImage()
291:                                 {
292:                                     CodeFile = GetValueString(cItem, "code_file"),
293:                                     ImageAddress = imageAddress,
294:                                     ImageSize = GetValueInt(cItem, "image_size"),
295:                                     DebugFile = GetValueString(cItem, "debug_file"),
296:                                     DebugId = GetValueString(cItem, "debug_id"),
297:                                     CodeId = GetValueString(cItem, "code_id"),
298:                                     Type = GetValueString(cItem, "type"),
299:                                 });
300:                             }
301:                         }
302:                     }
303:                 }
304:             }
305:             finally
306:             {
307:                 sentry_value_decref(cList);
308:             }
309:         }
310:         catch (Exception e)
311:         {
312:             logger?.LogWarning(e, "Error loading the list of debug images");
313:         }
314:         return result;
315:     }
